css:
:scope{--cream:var(--os-color-background);--paper:#f6f1e4;--brown:#472d1e;--clay:var(--os-color-accent);--ink:var(--os-color-text);--serif:'Cormorant Garamond',Georgia,serif;--sans:'Hanken Grotesk',system-ui,sans-serif;--gap:clamp(56px,9vw,120px)}
:scope{color:var(--ink);font-family:var(--sans);font-size:17px;line-height:1.7}
:where(h1,h2,h3,h4,h5,h6){color:inherit;font-family:inherit;font-weight:bold;font-style:inherit;letter-spacing:normal;text-transform:none;line-height:inherit;text-wrap:wrap}
:where(h1){font-size:2em}:where(h2){font-size:1.5em}:where(h3){font-size:1.17em}:where(h4){font-size:1em}:where(h5){font-size:.83em}:where(h6){font-size:.67em}
:where(.os-ci){display:inline-block;max-width:100%;vertical-align:middle;aspect-ratio:auto}
.os-ci>picture{display:contents}
.os-ci img{display:block;width:100%;height:100%;object-fit:inherit;object-position:inherit;border-radius:inherit}
*{box-sizing:border-box}
h2,h3{font-family:var(--serif);color:var(--brown);font-weight:500;line-height:1.15;margin:0 0 .5em}
h2{font-size:clamp(2rem,4.5vw,3.1rem)}
h3{font-size:1.6rem}
p{margin:0 0 1.1em;max-width:62ch}
.wrap{max-width:1080px;margin:0 auto;padding:0 24px}
section{padding:var(--gap) 0}
.kicker{text-transform:uppercase;letter-spacing:.18em;font-size:.8rem;color:var(--clay);margin-bottom:1.2em}
.paper{background:var(--paper)}
.center{text-align:center}
.center p{margin-left:auto;margin-right:auto}
.grid{display:grid;gap:24px;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));margin-top:2.2em}
.card{background:var(--cream);border:1px solid #e3d6bd;border-radius:18px;padding:28px}
.paper .card{background:var(--cream)}
.card .sub{font-size:.8rem;text-transform:uppercase;letter-spacing:.14em;color:var(--clay);margin-bottom:.8em}
.card p:last-child{margin-bottom:0}
:scope:scope:scope .s-1{margin:2em auto 0}
